import React from 'react';

export function MarkdownText({ content }: { content: string }) {
  const lines = content.split('\n');
  return <div className="markdown-text">{lines.map((line, index) => {
    if (line.startsWith('## ')) return <h4 key={index}>{line.slice(3)}</h4>;
    if (line.startsWith('- ')) return <div className="markdown-bullet" key={index}><span>•</span><span>{formatInline(line.slice(2))}</span></div>;
    if (!line.trim()) return <div className="markdown-gap" key={index} />;
    return <p key={index}>{formatInline(line)}</p>;
  })}</div>;
}

function formatInline(value: string) {
  const parts = value.split(/(\*\*.*?\*\*|`.*?`)/g);
  return parts.map((part, index) => part.startsWith('**') ? <strong key={index}>{part.slice(2, -2)}</strong> : part.startsWith('`') ? <code key={index}>{part.slice(1, -1)}</code> : part);
}
